import sys

data = sys.stdin.read().split()
n = int(data[0])
prod = []
for i in range(n):
    prod.append((data[1 + 2 * i], data[2 + 2 * i]))
m = int(data[1 + 2 * n])
items = data[2 + 2 * n:2 + 2 * n + m]
ds = []
for it in items:
    for p, d in prod:
        if p == it:
            ds.append(d)
            break
old = 1
for i in range(1, len(ds)):
    if ds[i] != ds[i - 1]:
        old += 1
new = []
for d in ds:
    if d not in new:
        new.append(d)
print(old - len(new))

